import{describe,it,expect,beforeEach}from"vitest";import{initGalleryLightbox,initSmoothScroll}from"../../lion-tailed-macaque-explorer/script.js";describe("Lion-tailed Macaque Explorer Page (#1314)",()=>{beforeEach(()=>{document.body.innerHTML='\n      <div id="gallery-lightbox" class="lightbox-modal" aria-hidden="true">\n        <span class="lightbox-close">&times;</span>\n        <img id="lightbox-img" src="" alt="">\n        <div id="lightbox-caption"></div>\n      </div>\n      <div class="gallery-item" data-caption="Test Caption">\n        <img src="test.png" alt="Test Alt">\n        <div class="gallery-caption">Test Caption</div>\n      </div>\n      <nav class="toc-nav">\n        <a href="#overview">Overview</a>\n      </nav>\n      <section id="overview"></section>\n    '}),it("exports functions correctly",()=>{expect(typeof initGalleryLightbox).toBe("function"),expect(typeof initSmoothScroll).toBe("function")}),it("opens and closes gallery lightbox modal on interaction",()=>{initGalleryLightbox();const e=document.getElementById("gallery-lightbox"),t=document.querySelector(".gallery-item"),i=document.querySelector(".lightbox-close");expect(e.getAttribute("aria-hidden")).toBe("true"),t.click(),expect(e.getAttribute("aria-hidden")).toBe("false"),i.click(),expect(e.getAttribute("aria-hidden")).toBe("true")})});